//! Exact lease descriptions and platform ports consumed by Storage, independent of networking.
use crate::modules::{
    identity::api::IdentityId,
    services::{Error, handler::Blob},
};

/// Immutable public byte identifier, generated by the provider rather than derived from content.
pub type LeaseId = [u8; 32];
/// SHA-256 over the exact logical stored bytes.
pub type ContentHash = [u8; 32];

/// Durable logical state; retained physical bytes do not imply an active obligation.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum State {
    /// Upload is incomplete and is not a successful lease.
    Receiving,
    /// Complete durably accepted obligation.
    Active,
    /// Retention ended; clock rollback cannot reactivate it.
    Expired,
    /// Owner ended the lease; no secure-erasure guarantee.
    Removed,
}

/// Owner-retained immutable lease description, without access to provider byte paths.
#[derive(Clone)]
pub struct Lease {
    /// Provider-unique unpredictable identifier, not bearer authority.
    pub id: LeaseId,
    /// Authenticated requester permitted to use the lease.
    pub requester: IdentityId,
    /// Identity responsible for this single copy.
    pub provider: IdentityId,
    /// Complete original offering snapshot in the owner's canonical representation.
    pub accepted_terms: Blob,
    /// Exact logical byte length, including requester encryption overhead.
    pub size_bytes: u64,
    /// SHA-256 of the complete logical object, including on ranged retrievals.
    pub content_hash: ContentHash,
    /// Completed durable acceptance time, in Unix seconds.
    pub accepted_at: u64,
    /// Checked expiration time, in Unix seconds.
    pub expires_at: u64,
    /// Exact original store charge, in credits of the accepted issuer.
    pub store_price: u64,
    /// Current logical state.
    pub state: State,
}

/// Clock observation separates UTC lease times from process-local elapsed time.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Time {
    /// Current UTC estimate, in whole Unix seconds.
    pub unix_seconds: u64,
    /// Elapsed whole seconds within this boot; never compare across boots.
    pub elapsed_seconds: u64,
    /// Opaque boot identity allowing detection of monotonic-clock resets.
    pub boot: [u8; 16],
}

/// Platform time source; composition documents its UTC correction/reboot assumptions.
pub trait Clock: Send + Sync {
    /// Observe UTC and elapsed time together without manufacturing a value on failure.
    /// # Errors
    /// Unavailable or invalid platform clocks fail explicitly.
    fn now(&self) -> Result<Time, Error>;
}

/// Injected cryptographic operations; no secret key is required for byte storage.
pub trait Crypto: Send + Sync {
    /// Generate one unpredictable candidate; the lease owner separately enforces uniqueness.
    /// # Errors
    /// Entropy failure is Unavailable; callers must not fall back to predictable IDs.
    fn lease_id(&self) -> Result<LeaseId, Error>;
    /// Hash exact supplied bytes without normalization or encryption.
    /// # Errors
    /// A failed hashing dependency cannot establish content validity.
    fn hash(&self, bytes: &[u8]) -> Result<ContentHash, Error>;
}

/// Durable owner-private snapshot port; adapters protect files and bound reads before allocation.
pub trait Persistence: Send + Sync {
    /// Read the latest acknowledged owner snapshot, or None for an unused store.
    /// # Errors
    /// Corruption, wrong version, excessive length and unavailable storage fail closed.
    fn load(&self, maximum_bytes: usize) -> Result<Option<Vec<u8>>, Error>;
    /// Atomically replace one owner snapshot with exact bytes and complete durability barriers.
    /// # Errors
    /// A possible committed write with a lost acknowledgement returns Unknown, never implied rollback.
    fn replace(&self, bytes: &[u8]) -> Result<(), Error>;
}

/// Finite local admission policy, independent of advertised per-operation terms.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Limits {
    /// Aggregate live and staged logical byte capacity.
    pub bytes: u64,
    /// Aggregate retained lease slots.
    pub leases: usize,
    /// Maximum simultaneous pending operations, including prepared holds.
    pub operations: usize,
    /// Aggregate retained result capacity in bytes.
    pub result_bytes: u64,
    /// Maximum simultaneous operations for one authenticated requester.
    pub per_owner: usize,
}
impl Limits {
    /// Reject unusable capacity before creating an owner or advertising a provider.
    /// # Errors
    /// Invalid denotes a zero limit or per-owner count exceeding aggregate operations.
    pub fn validate(self) -> Result<Self, Error> {
        tracing::trace!("Validating finite Storage admission limits");
        if self.bytes == 0
            || self.leases == 0
            || self.operations == 0
            || self.result_bytes == 0
            || self.per_owner == 0
            || self.per_owner > self.operations
        {
            return Err(Error::Invalid);
        }
        Ok(self)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    // Every quota must be positive and per-owner work must fit the aggregate capacity.
    #[test]
    fn limits_reject_unusable_and_inconsistent_capacity() {
        let good = Limits {
            bytes: 1,
            leases: 1,
            operations: 2,
            result_bytes: 1,
            per_owner: 2,
        };
        assert_eq!(good.validate(), Ok(good));
        for bad in [
            Limits { bytes: 0, ..good },
            Limits { leases: 0, ..good },
            Limits {
                operations: 0,
                ..good
            },
            Limits {
                result_bytes: 0,
                ..good
            },
            Limits {
                per_owner: 0,
                ..good
            },
            Limits {
                per_owner: 3,
                ..good
            },
        ] {
            assert_eq!(bad.validate(), Err(Error::Invalid));
        }
    }
    // Exact uint64 times and sizes do not pass through a floating-point representation.
    #[test]
    fn widths_and_terminal_states_are_explicit() {
        let time = Time {
            unix_seconds: u64::MAX,
            elapsed_seconds: u64::MAX,
            boot: [1; 16],
        };
        assert_eq!(time.unix_seconds, 18_446_744_073_709_551_615);
        assert_ne!(State::Active, State::Receiving);
        assert_ne!(State::Active, State::Expired);
        assert_ne!(State::Active, State::Removed);
    }
}
